      SUBROUTINE CAB3(RC,TC,UC,RA,TA,UA,RB,TB,UB)CC     CALCULATES MATRIX PRODUCT IN THIRD ORDERCC     LIST OF COMMON BLOCKSC      INCLUDE 'TMUL.CIN'      INCLUDE 'UMUL.CIN'CC     LOCAL VARIABLESC      INTEGER  I1, I2, I3, I4, I5, I6, I7, I234, I1MIN      INTEGER  INDA, INDB, INDEX3      REAL  RA(6,6), RB(6,6), RC(6,6)      REAL  S, TA(5,21), TB(5,21), TC(5,21), TR, TT      REAL  UA(5,56), UB(5,56), UC(5,56)      REAL  UR(6), URRCC------------------------------------------------------      CALL CAB2(RC,TC,RA,TA,RB,TB)CC     FIND WHICH ROWS SHOULD BE MULTIPLIEDC      UMUL = .FALSE.      DO 10 I1 = 1, 5      DO 10 I234 = 1, 56      IF (UA(I1,I234) .NE. 0.0) THEN        UMUL = .TRUE.        GO TO 50      ENDIF   10 CONTINUECC     PART OF UC FROM RA X UBC   50 DO 90 I1 = 1, 5      DO 90 I234 = 1, 56      S = 0.0      DO 80 I5 = 1, 5      S = S + RA(I1,I5)*UB(I5,I234)   80 CONTINUE      UC(I1,I234) = S   90 CONTINUECC     PART OF UC FROM UA X RB X RB X RBC      IF (.NOT. UMUL) GO TO 300      DO 150 I1 = 1, 5      DO 150 I2 = 1, 6      INDA = 0      DO 150 I7 = 1, 6      DO 110 I6 = 1, I7      UR(I6) = 0.0      DO 110 I5 = 1, I6      INDA = INDA + 1      UR(I6) = UR(I6) + UA(I1,INDA)*RB(I5,I2)  110 CONTINUEC      DO 140 I3 = 1, 6      URR = 0.0      DO 120 I6 = 1, I7      URR = URR + UR(I6)*RB(I6,I3)        120 CONTINUE      IF (URR .EQ. 0.0) GO TO 140C      DO 130 I4 = 1, 6      I234 = INDEX3(I2,I3,I4)      UC(I1,I234) = UC(I1,I234) + URR*RB(I7,I4)  130 CONTINUE  140 CONTINUE  150 CONTINUECC     PART OF UC FROM TA X RB X TBC      IF (.NOT. TMUL) GO TO 300      I1MIN = 1      IF (.NOT. TMULT) I1MIN = 5C      DO 200 I1 = I1MIN, 5      DO 200 I2 = 1, 6      INDA = 0      DO 200 I6 = 1, 5      TR = 0.0      DO 160 I5 = 1, I6      INDA = INDA + 1      TR = TR + TA(I1,INDA)*RB(I5,I2)  160 CONTINUEC      IF (TR .EQ. 0.0) GO TO 200      INDB = 0      DO 170 I4 = 1, 6      DO 170 I3 = 1, I4      INDB = INDB + 1      I234 = INDEX3(I2,I3,I4)      UC(I1,I234) = UC(I1,I234) + TR*TB(I6,INDB)  170 CONTINUE  200 CONTINUECC     PART OF UC FROM TA X TB X RBC      DO 250 I1 = I1MIN, 5      INDB = 0      DO 250 I3 = 1, 6      DO 250 I2 = 1, I3      INDB = INDB + 1      INDA = 0      DO 250 I6 = 1, 6      TT = 0.0      DO 210 I5 = 1, I6      INDA = INDA + 1      IF (I5 .EQ. 6) GO TO 210      TT = TT + TA(I1,INDA)*TB(I5,INDB)  210 CONTINUEC      IF (TT .EQ. 0.0) GO TO 250      DO 220 I4 = 1, 6      I234 = INDEX3(I2,I3,I4)      UC(I1,I234) = UC(I1,I234) + TT*RB(I6,I4)  220 CONTINUE  250 CONTINUEC  300 RETURN      END